import React, { useRef, useContext } from 'react';
import { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from "axios";
import { calculate_genre, calculate_score, num_to_month } from '../../utilities/util2';
import { capitalize_first_letter } from '../../utilities/extra.js';
import  Stats  from './stats.js';
import { ContextHead } from '../../App.js';
import txt  from '../../settings/setting.json'

axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.xsrfHeaderName = "x-csrftoken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
})

const genres = ["adventure", "action", "avant garde", "award winning", "boys love ", "comedy", "drama", "fantasy", "girls Love", "gourmet", "horror", "mystery", "romance", "sci-fi", "slice of life", "sports", "school", "supernatural", "suspense"]

export default function View(props) {
  const [user_info, setInfo] = useState({"main":{}});
  const [name, setName] = useState("");
  const [loading_name, setLoadingName] = useState("");
  const [load, setLoaded] = useState(false);
  const location = useLocation();
  const scores = useRef([]);
  const [user_date, set_date] = useState(new Date);
  const ctx = useContext(ContextHead);
  const navigate = useNavigate();
  const changer = txt.changer;

  //var name = "";

  function redirect(anime_id){
    navigate(`/anime/${anime_id}`);
  }

  function get_title(object){
    if(JSON.parse(localStorage.getItem("title_lang"))){
      if(object.japanese_name != ""){
        return object.japanese_name;
      }else{
        return object.english_name;
      }
    }else{
      if(object.english_name != ""){
        return object.english_name;
      }else{
        return object.japanese_name;
      }
    }
  }

  function leaper(year){const current = new Date();if(year % 4 == 0){return 29;}return 28;}
  
  function days_difference(cur, cur_year,years, cur_month, months, dim){
    const days_after_opening = dim[user_info.date_joined.getMonth()] - user_info.date_joined.getDate();
    const currentDay = cur.getDate();
    
    //for same month same year
    if(years == 0 && months == 0){return currentDay-user_info.date_joined.getMonth()}
    
    let days = 0;
    outter:for(let i = user_info.date_joined.getFullYear(); i < cur_year+1; i++){
      let setter = 0;
      let final_month = cur_month;
      if(i == user_info.date_joined.getFullYear()){setter = user_info.date_joined.getMonth(); final_month=12}
      for(let k = setter; k < final_month; k++){
        //console.log(k, dim[k])
        if(k == 1){
          days += (leaper(i));
        }if(k == 11){
          if(cur_year == i){
            days += cur.getDate();
          }else{days += (dim[k])}
        }
        else{
          if(cur_month == k){
            //console.log(k, cur.getDate())
            days+=cur.getDate();
            if(cur_year == user_info.date_joined.getFullYear()){break;}
          }else{days+=dim[k]}
        }
      }
    }

    days = days - dim[user_info.date_joined.getMonth()] + days_after_opening  + 1;
    //console.log(days)
    //for less than a year but different month
  }
  function load_user_side_stuff(){
    const user_el = document.getElementsByClassName("userV_info_vals");
    const cur = new Date();
    const days_in_month = [31,leaper(cur.getFullYear()),31,30,31,30,31,31,30,31,30,31]
    const currentYear = cur.getFullYear(); const currentMonth = cur.getMonth();
    const years_joined = currentYear - user_info.date_joined.getFullYear();/*user_date.getFullYear()*/ const months_joined = currentMonth - user_info.date_joined.getMonth();
    days_difference(cur, currentYear, years_joined, currentMonth, months_joined, days_in_month)
    let y_s = "Years";
    //console.log(months_joined)
    if(years_joined == 1){y_s = "Year"}
    user_el[0].appendChild(document.createTextNode(num_to_month(user_info.date_joined.getMonth()) + " " + user_info.date_joined.getDate() + ", " + user_info.date_joined.getFullYear() + ` (~${years_joined} ${y_s})`));
    user_el[1].appendChild(document.createTextNode(user_info.completed))
    user_el[2].appendChild(document.createTextNode(user_info.episodes))
  }
  useEffect(()=>{
    try{load_user_side_stuff();}catch{return;}
  }, [load]);
  useEffect(()=>{
    async function partner(){
      let temp_name = window.location.href.match(/(\w+){1}$/g) + "'s";
      let temp_name_no_s = window.location.href.match(/(\w+){1}$/g);
      setLoadingName(temp_name);
      setName(temp_name_no_s);

      //add a try catch here
      const MORE_DATA = await client.get(`view_user_ani_get/${temp_name_no_s}`);
      let date_joined = new Date(MORE_DATA.data["resp"]["date_joined"]);
      MORE_DATA.data["resp"]["date_joined"] = date_joined;
      setInfo(MORE_DATA.data["resp"]);
      set_date(date_joined);
      setLoaded(true);
    }

    partner();
    
  }, [location]);

  return (<>
  {load ? <>
  <div className='cluster_user_info'>
    <div className="view_area">
      <div>
        <p style={{"fontSize":"20px", "margin":"0", "padding":"10px 0px 10px 0px", "backgroundColor":"#333", "color":"white", "textAlign":"center"}}>{/*This Page Will Come In Like a Lion. Coming Soon By The Way.*/}{name}</p> 
        <div className="user_img_pfp">
          <img src={process.env.PUBLIC_URL + "/img/placeholderImg.jpg"} height="200px" width="100%"/>
          <button className="regular_btn" id="user_pf_anilist" style={{textAlign:"center"}}>Anime List (Soon)</button>
        </div>
        <div className='info_views'><p className='user_info_yoinks'>Date Joined: </p> <span className='userV_info_vals'></span></div>
        <div className='info_views'><p className='user_info_yoinks'>Anime Completed: </p> <span className='userV_info_vals'></span></div>
        
        <hr className='user_subdivision_divide'/>

        <div className="user_subdivision">
          <h4>Episode Stats:</h4>
          <div className='info_views'><p className='user_info_yoinks'>Episodes Watched (Total): </p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Episodes Watched (Today): N/A</p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Episodes Watched (Week): N/A</p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Episodes Watched (Year): N/A</p> <span className='userV_info_vals'></span></div>
        </div>
        
        <hr className='user_subdivision_divide'/>

        <div className="user_subdivision">
          <h4>Anime Stats:</h4>
          <div className='info_views'><p className='user_info_yoinks'>Most Watched Studio: N/A</p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Average Scores: N/A</p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Favorite Genre: N/A</p> <span className='userV_info_vals'></span></div>
          <div className='info_views'><p className='user_info_yoinks'>Number of Reviews: N/A </p> <span className='userV_info_vals'></span></div>
        </div>
      </div>
    </div>
    <div className="view_area">
      <h1 id="userPage_name" style={{textAlign:"center", "color":"white"}}>{name}'s Stats</h1>
      <Stats getTitle={get_title} info={user_info} changer={changer} redir={redirect} user={name}/>
    </div>
  </div>
  </>
  : <div style={{"textAlign":"center", "marginTop":"50px"}}>
      <div class="loader"></div>
      <span id="loading_id">Loading {loading_name} Page</span>
    </div>
  }
    
  </>)
}