import React, { Component, useEffect, useState, useContext } from 'react';
import { useLocation } from 'react-router-dom';
import { getCookie, send_review } from '../utilities/extra';
import Modal from "react-modal";
import axios from 'axios';
import ViewerIn from './reviewViewers/reviewViewer';
import ViewerOut from './reviewViewers/reviewViewerOut';
import { AnimeDetailsCTX } from '../AccountsComp/Anime_detail';

axios.defaults.xsrfHeaderName = "X-CSRFTOKEN";
axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
});
const baseURL = "https://infernovertigo.pythonanywhere.com";

const customStyles = {
  content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    width: '80%',
    backgroundColor: "black",
    backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  },
  overlay:{
    backgroundColor: 'rgba(0, 0, 255, 0.03)',
    position:'fixed',
    //backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  }
};
let el = document.getElementById('root') || undefined;
let subtitle;

function word_count(){
  const count = document.getElementById("count");
  const textArea = document.getElementById("review_box");

  const length = textArea.value.trim().length;
  count.innerText = length.toString();

  if(length == 1000){count.style.color="red"}
  else{count.style.color="orange"}
}

const ReviewModal = (props) =>{
  const value = useContext(AnimeDetailsCTX);
  useEffect(()=>{
    //console.log(props.valid, props.loggedIn)
  })
  return(
  <>
    <div id="review_cont">
    <Modal
        isOpen={props.show}
        onAfterOpen={null}
        onRequestClose={props.closeModal}
        style={customStyles}
        contentLabel="Example Modal"
        appElement={el}
        animationType="fade"
        //className="Modal"
        //overlayClassName="Overlay"
      >
        <h2 id="review_area_header">{value.title}</h2>
        <div id="user_stats_review">

        </div>
        
        {value.loggedIn && value.valid? <><ViewerIn value={value} closeModal={props.closeModal}/>
        </> : <><ViewerOut closeModal={props.closeModal} loggedIn={value.loggedIn} status={value.status} valid={!value.valid} /></>}
      </Modal>
    </div>
  </>)
}

export default ReviewModal;