import {React, useEffect, useState} from 'react'
import  Genregraph  from './UserPages/genregraph.js'
import {to_form_data, getCookie, month_to_str} from '../../utilities/extra'
import Recentadded from './recentadded.js';
import { dummy } from './UserPages/actionables.js';
import Modal from "react-modal";

const origin_url = "https://infernovertigo.pythonanywhere.com/";
let el;

const customStyles = {
  content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    width: '60%',
    backgroundColor: "black",
    backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  },
  overlay:{
    backgroundColor: 'rgba(0, 0, 255, 0.03)',
    position:'fixed',
    //backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  }
};

export default function Stats(props) {
  const [graphAppear, setGraph] = useState(<></>);
  const [modalIsOpen, setIsOpen] = useState(false);

  function text(str){
    return document.createTextNode(str);
  }
  function closeModal(){
    setIsOpen(false);
  }function afterOpenModal(){
    //do nothing
  }function openModal(){
    setIsOpen(true);
  }

  useEffect(()=>{
    async function get_recents(){
      const leech = {"session":getCookie("sessionid"), "csrf":getCookie("csrftoken")};
      const recents = await fetch(origin_url+"view/latest", {method:"POST",
        body:JSON.stringify(leech),
        headers:{
          "Content-Type":"application/json"
        }
      }).then((data)=>data.json());
      //console.log(recents);
      const recents_cont = document.getElementById("recents");
      for(let i = 0; i < recents.user_stats.length; i++){
        const split_vals = recents.user_stats[i].split(" ");
        //0 = id, 1 = score, 2 = watched, 3 = date updated unix millis
        const id = split_vals[0];
        const score = split_vals[1];
        const watched = split_vals[2]
        const unix = new Date(Number(split_vals[3]));
        let hour = 0;
        const prefix = "A.M."
        if(unix.getUTCHours() == 0){
          hour = 12;
        }
        else if(unix.getUTCHours() < 13){
          hour = unix.getUTCHours();
        }else{
          hour = unix.getUTCHours() - 12;
        }
        if(unix.getUTCHours() > 11){
          prefix = "P.M."
        }
        //console.log(unix.toUTCString())
        const time = month_to_str(unix.getMonth()) + " " + unix.getDate() + ", " + unix.getFullYear() + " " + hour + ":" + unix.getMinutes() + " " + prefix;

        //loop and find in the data arrays the corresponding val in order
        for(let k = 0; k < recents.data.length; k++){
          if(recents.data[k].anime_id == id){
            //console.log("match")
            //start building the elements
            const outter_main_recent_container = document.createElement("div");
            outter_main_recent_container.setAttribute("class", "full_recent_container");

            const title = document.createElement("h4");
            title.style.marginBottom = "2px";
            title.style.textAlign = "center";
            
            title.appendChild(text(props.getTitle(recents.data[k])));
            title.setAttribute("class", "recent_sub_title");
            outter_main_recent_container.appendChild(title);

            const recent_container = document.createElement("div");
            recent_container.style.display = "flex";

            const img_div = document.createElement("div");
            const img = document.createElement("img");
            img.setAttribute("class", "recent_sub_img");
            img.style.width = "121";
            img.style.height = "200px";
            img.src = recents.data[k].img_url;
            img_div.appendChild(img);
            recent_container.appendChild(img_div);

            //information stuff
            const info_div = document.createElement("div");

            const episodes = document.createElement("p");
            episodes.setAttribute("class", "recent_sub_info");
            episodes.appendChild(text("Episodes: " + watched + "/" + recents.data[k].episodes))
            
            const Score = document.createElement("p");
            Score.setAttribute("class", "recent_sub_info");
            Score.appendChild(text("Score: " + score + "/10"))
            
            const date_updated = document.createElement("p");
            date_updated.setAttribute("class", "recent_sub_info");
            date_updated.appendChild(text("Updated: " + time));

            info_div.appendChild(episodes); info_div.appendChild(Score); 
            info_div.appendChild(date_updated);

            info_div.style.flexGrow = "1";
            info_div.style.textAlign = "left";
            recent_container.appendChild(info_div);

            outter_main_recent_container.appendChild(recent_container);
            recents_cont.appendChild(outter_main_recent_container);
            //const info_div = document.createElement("div");
          }
        }
      }
    }


    const area = document.getElementById("outter_entries_stats");
    //console.log(props);

    //const dokidoki = document.getElementById("entries_stat_cont");
    const dokidoki = document.getElementById("entries_stat_watched");
    dokidoki.style.width = "350px";
    const temp = props;
    props = props.info;
    //do some math you maggots
    const total = props.completed+props.dropped+props.plan+props.unfini+props.watching;//ignore entries
    const completed_perc = (props.completed/total)*100;
    const dropped_perc = (props.dropped/total)*100;
    const plan_perc = (props.plan/total)*100;
    const unfinished_perc = (props.unfini/total)*100;
    const watching_perc = (props.watching/total)*100;
    
    const widths = [Math.floor(completed_perc), Math.floor(dropped_perc), Math.floor(plan_perc), Math.floor(unfinished_perc), Math.floor(watching_perc)];
    const colors = ["green", "red", "gray", "purple", "blue"]
    const category = ["Completed", "Dropped", "Plan To Watch", "Unfinished", "Watching"];
    const numbers = [props.completed, props.dropped, props.plan, props.unfini, props.watching];

    for(let i = 0; i < 5; i++){
      const el = document.createElement("p");
      el.style.height = "20px";
      el.style.width = (widths[i])+"%";
      el.style.backgroundColor = colors[i];
      el.style.display = "inline-block";
      el.style.marginRight = "0px";
      dokidoki.appendChild(el);
    }

    let counter = 0;
    const legend_area = document.createElement("div");
    legend_area.setAttribute("id", "user_watch_legend");

    for(let k = 0; k < 5; k++){
      const row = document.createElement("div");

      const color_square = document.createElement("span");
      color_square.setAttribute("class", "user_legend_color_squares");
      color_square.style.display = "inline-block";
      color_square.style.backgroundColor = colors[k];

      const category_name = document.createElement("p");
      category_name.setAttribute("class", "user_legend_names");
      category_name.style.display = "inline-block";
      category_name.appendChild(text(category[k]+":"));

      const num_made_up = document.createElement("span");
      num_made_up.setAttribute("class", "user_legend_vals");
      num_made_up.style.display = "inline-block";
      num_made_up.appendChild(text(numbers[k]));

      row.appendChild(color_square);
      row.appendChild(category_name);
      row.appendChild(num_made_up);
      legend_area.appendChild(row);
    }
    dokidoki.appendChild(legend_area);
    //dokidoki.innerHTML = dokidoki.innerHTML + "<button class='compare_btn regular_btn'>Compare</button>"
    const compare_btn = document.createElement("button");
    compare_btn.setAttribute("class", "compare_btn regular_btn");
    compare_btn.innerText = "Compare";
    compare_btn.addEventListener("click", function(e){
      dummy(openModal, text);
    })
    dokidoki.appendChild(compare_btn);

    setGraph(<Genregraph htext={text}/>)
    
    //for loading recents
    const recent_section = document.getElementById("recents_area");
    recent_section.style.textAlign = "right";
    props = temp;
    //get_recents();
  }, [])

  function put_in_graph(){

  }
  return (
    <>
      <Modal
        isOpen={modalIsOpen}
        onAfterOpen={afterOpenModal}
        onRequestClose={closeModal}
        style={customStyles}
        contentLabel="Example Modal"
        appElement={el}
        animationType="fade"
        ariaHideApp={false}
        //className="Modal"
        //overlayClassName="Overlay"
      > 
      <div id="genre_summary_modal">
        
      </div>
      </Modal>

      <div id="outter_entries_stats">
      
      <div id="entries_stat_cont">
        <div id="entries_stat_watched">
          <h3 style={{textAlign:"center", color:"white"}}>Anime Alley</h3>
        </div>
        {graphAppear}
      </div>
      <div id="recents_area">
        <h3 style={{textAlign:"center", color:"white"}}>Recently Updated</h3>
        {/*<div id="recents">
          
        </div>*/}
        <Recentadded changer={props.changer} redir={props.redir} user={props.user}/>
      </div>
    </div>
    </>
  )
}