import React, { useRef } from 'react';
import { useEffect, useState } from 'react';
import axios from "axios";
import { BarChart } from '@mui/x-charts/BarChart';
import { axisClasses } from '@mui/x-charts/ChartsAxis';
import { calculate_genre, calculate_score, num_to_month } from '../../../utilities/util2.js';
import { capitalize_first_letter } from '../../../utilities/extra.js';
import { createHover, dummy } from './actionables.js';
import Modal from "react-modal";

axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.xsrfHeaderName = "x-csrftoken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
})

const genres = ["adventure", "action", "avant garde", "award winning", "boys love ", "comedy", "drama", "fantasy", "girls Love", "gourmet", "horror", "mystery", "romance", "sci-fi", "slice of life", "sports", "school", "supernatural", "suspense"]

const customStyles = {
  content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    width: '60%',
    backgroundColor: "black",
    backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  },
  overlay:{
    backgroundColor: 'rgba(0, 0, 255, 0.03)',
    position:'fixed',
    //backgroundImage:"url(https://t3.ftcdn.net/jpg/03/08/13/12/360_F_308131267_unLRF2JmPsjjXgrMRaFA3aEnrKa9aUxK.jpg)"
  }
};
let el;

export default function Genregraph(props) {
  const genre = useRef([]);
  const [avgScore, setAvgScore] = useState(0);
  const [fixMargin, setFixMargin] = useState(true);
  const [fixLabel, setFixLabel] = useState(true);
  const tLabel_size=14;
  const tLabel_color="#ffffff";

  const [load, setLoaded] = useState(false);
  const scores = useRef([]);
  const [user_date, set_date] = useState(new Date);

  const [modalIsOpen, setIsOpen] = React.useState(false);

  const valueFormatter = (value) => `${value}`;

  function closeModal(){
    setIsOpen(false);
  }function afterOpenModal(){
    //do nothing
  }function openModal(){
    setIsOpen(true);
  }

  function load_genre_stats(results){
    //console.log("ccalled")
    //Class: .genre_num_human
    const main_cont = document.getElementsByClassName("genre_num_humans_cont")[0];
    try{
      for(let h = main_cont.childNodes.length-1; h >= 0; h--){
        main_cont.removeChild(main_cont.childNodes[h]);
      }

      let counter = 0;
      const max = 3;
      let current = 0;
      let fav_genre = "";
      let lowest = results[0].amt;
      let hated_genre = "";
      let cont_el;
      outter:for(let i = 0; i < genres.length; i++){
        if(counter == 0){
          cont_el = document.createElement("div");
          cont_el.setAttribute("class", "genre_num_human");
          cont_el.style.display = "flex";
          cont_el.style.width="100%";
        }
        for(let b = 0; b < results.length; b++){
          if(capitalize_first_letter(genres[i]) == results[b].Genres){
            counter+=1;
            if(current < results[b].amt){
              current=results[b].amt;
              fav_genre=results[b].Genres;
            }if(results[b].amt < lowest){
              lowest = results[b].amt;
              hated_genre = results[b].Genres;
            }
            //create new element
            const el = document.createElement("p")
            el.setAttribute("class", "genre_cats")
            el.setAttribute("id", results[b].Genres)
            el.setAttribute("title", results[b].Genres)
            el.style.position = "relative";

            //the info box of info hoorayyy
            
            el.addEventListener("click", function(e){
              createHover(e, results[b].Genres.replace(" ","-"), openModal, props.htext, results[b].Genres);
            });

            const textEl = document.createElement("span")
            //textEl.setAttribute("id", results[b].Genres)
            textEl.setAttribute("class","genre_cats_val");
            textEl.appendChild(document.createTextNode(results[b].amt))
            const textNode = document.createTextNode(results[b].Genres + ": ")
            el.appendChild(textNode); el.appendChild(textEl)
            el.style.flex="1";
            el.style.width="100%";
            cont_el.appendChild(el)

            if(counter == max){
              counter = 0;
              main_cont.appendChild(cont_el);
              break;
            }
          }
        }
      }
      document.getElementById(fav_genre).style.color = "#990";
      document.getElementById(hated_genre).style.color = "#900";
      document.getElementById(fav_genre).style.fontWeight = "bolder";
      document.getElementById(hated_genre).style.fontWeight = "bolder";
      /*document.getElementById(fav_genre).style.backgroundColor = "#990";
      document.getElementById(hated_genre).style.backgroundColor = "#900";*/
    }catch{
      console.log("problem")
      return;
    }
  }
  function load_score_stats(results){
    const main_cont = document.getElementsByClassName("genre_num_humans_cont")[1];
    
    let counter = 0;
    const max = 3;
    let cont_el;

    outter:for(let i = 0; i < scores.current.length; i++){
      if(counter % 3 == 0){
        cont_el = document.createElement("div");
        cont_el.setAttribute("class", "genre_num_human");
        cont_el.style.display = "flex";
        cont_el.style.width="100%";
      }
      const el = document.createElement("p")
      el.setAttribute("class", "genre_cats")
      const textEl = document.createElement("span")
      textEl.setAttribute("id", results[i].Genres)
      textEl.setAttribute("class","genre_cats_val");
      textEl.appendChild(document.createTextNode(results[i].Amt))
      const textNode = document.createTextNode(results[i].Score + ": ")
      el.appendChild(textNode); el.appendChild(textEl)
      el.style.flex="1";
      el.style.width="100%";
      cont_el.appendChild(el)

      counter+=1;
      if(counter % max == 0){
        main_cont.appendChild(cont_el);
      }
    }

    const avg_label = document.createElement("p");
    avg_label.innerHTML="Average Ratings: "
    avg_label.setAttribute("id","avg_label");

    const avg_val = document.createElement("span");
    avg_val.innerText = avgScore.toFixed(2);
    avg_val.setAttribute("id", "avg_val")

    avg_label.appendChild(avg_val)
    main_cont.appendChild(avg_label)
  }
  function load_user_side_stuff(){
    const join_el = document.getElementsByClassName("userV_info_vals")[0];
    //console.log(join_el)
    const currentYear = new Date().getFullYear();
    const years_joined = currentYear - user_date.getFullYear()
    let y_s = "Years";
    if(years_joined == 1){y_s = "Year"}
    join_el.appendChild(document.createTextNode(num_to_month(user_date.getMonth()) + " " + user_date.getDate() + ", " + user_date.getFullYear() + ` (~${years_joined} ${y_s})`));
  }
  /*useEffect(()=>{
    if(load){
      document.addEventListener('readystatechange', function() {
        if (document.readyState === 'complete') {
          // good luck!
          console.log('React app DOM is fully loaded.');
          
          load_genre_stats(genre.current);
          load_score_stats(scores.current);
          load_user_side_stuff();
        }
      })
      if(document.readyState == "complete"){
        //console.log("true")
        load_genre_stats(genre.current);
        load_score_stats(scores.current);
        load_user_side_stuff();
      }
    }
    
  }, [load])*/

  useEffect(()=>{
    let temp_name_no_s = window.location.href.match(/(\w+){1}$/g);
    async function partner(){
      const resp = await client.post("/view_user_A", {
        "username":temp_name_no_s
      }, {
        "headers":{
          "Content-Type":"application/json"
        }
      }).then((data)=>{return data.data;});

      const resp_scores = await client.post("/view_user_B",{
        "username":temp_name_no_s
      }, {
        "headers":{
          "Content-Type":"application/json"
        }
      }).then((data)=>{return data.data;});

      let date_joined = new Date(resp["date_joined"]);
      const genres_combined = resp["genres"];
      const resp_scores_combined = resp_scores["scores"];
      genre.current = [];
      const genre_obj = calculate_genre(genres, genres_combined);
      const score_obj = calculate_score(resp_scores_combined);
      setAvgScore(score_obj[0]);
      for(let item of Object.entries(genre_obj)){
        let temp = {};
        temp[item[0]] = item[1]
        temp["Genres"] = item[0]
        temp["amt"] = item[1]

        genre.current.push(temp)
      }
      for(let item of Object.entries(score_obj[1])){
        let temp = {};
        temp["Score"] = item[0]
        temp["Amt"] = item[1]

        scores.current.push(temp);
      }
      //console.log(scores);
      //console.log(genre);
    }
    partner();
    setTimeout(()=>{
      load_genre_stats(genre.current);
    }, 2000);
  }, [])

  return(
    <>
    <Modal
        isOpen={modalIsOpen}
        onAfterOpen={afterOpenModal}
        onRequestClose={closeModal}
        style={customStyles}
        contentLabel="Example Modal"
        appElement={el}
        animationType="fade"
        ariaHideApp={false}
        //className="Modal"
        //overlayClassName="Overlay"
      > 
      <div id="genre_summary_modal">
        
      </div>
      </Modal>

      <hr style={{margin:0}}/>
      <div id='genre_graph'>
        <BarChart
          leftAxis={{
            tickLabelStyle:{
              fontSize:`${tLabel_size}`,
              fill:`${tLabel_color}`,
              /*fontWeight:"bolder"*/
            }
          }}

          bottomAxis={{
            tickLabelStyle:{
              fontSize:`${tLabel_size}`,
              fill:`${tLabel_color}`
            }
          }}

          dataset={genre.current}
          margin={fixMargin ? { top: 30, right: 20, bottom: 30, left: 110 } : undefined}
          
          slotProps={{
            legend:{
              direction: 'row',
              position: { vertical: 'top', horizontal: 'middle' },
              padding:0,
              labelStyle: {
                fontSize: 19,
                fill: `${tLabel_color}`,
              },
            }
          }}
          
          yAxis={[
            { scaleType: 'band', dataKey: 'Genres'}
          ]}
          series={[
            { dataKey: 'amt', label: "Genres",valueFormatter }
          ]}
          
          layout="horizontal"
          
          height={400}
        />
      </div>
      <div className="genre_num_humans_cont">
          
      </div>

      <div className="view_legend">
        <div>
          <p style={{width:"21px", height:"21px", backgroundColor:"#990", margin:0}}></p><span>Favorite Genre</span>
        </div>
        <div>
          <p style={{width:"21px", height:"21px", backgroundColor:"#900", margin:0}}></p><span>Least Favorite Genre</span>
        </div>
      </div>
      <button onClick={(e)=>{dummy(openModal, props.htext)}} className='compare_btn regular_btn'>Compare</button>
    
    {/*<div id="score_weekly_daily_cont">
      <h1 style={{textAlign:"center", "color":"white", "width":"100%"}}>Score Distrobution</h1>
    
      <div className="scores_distro">
        <BarChart
          leftAxis={{
            tickLabelStyle:{
              fontSize:`${tLabel_size}`,
              fill:`${tLabel_color}`,
              fontWeight:"bolder"
            }
          }}

          bottomAxis={{
            tickLabelStyle:{
              fontSize:`${tLabel_size}`,
              fill:`${tLabel_color}`,
              fontWeight:"bolder"
            }
          }}

          dataset={scores.current}
          margin={fixMargin ? { top: 25, right: 15, bottom: 30, left: 0 } : undefined}
          
          slotProps={{
            legend:{
              direction: 'row',
              position: { vertical: 'top', horizontal: 'middle' },
              padding:0,
              labelStyle: {
                fontSize: 19,
                fill: '#a200ff',
              },
            }
          }}
          
          yAxis={[
            { scaleType: 'band', dataKey: 'Score'}
          ]}
          series={[
            { dataKey: 'Amt', label: "Scores", valueFormatter }
          ]}
          
          layout="horizontal"
          
          width={500}
          height={400}
        />
        <div className="genre_num_humans_cont">
            
        </div>
      </div>
    </div>*/}
  </>
  )
}