import React, { Component, useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { getCookie, send_review } from '../../utilities/extra';
import { Link } from 'react-router-dom';
import Modal from "react-modal";
import axios from 'axios';
import View from '../../User_Links/user_views/view';

axios.defaults.xsrfHeaderName = "X-CSRFTOKEN";
axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.withCredentials = true;

function ViewerOut(props){
  function go_to_add(){
    props.closeModal();
  }
  return(<>
    {!props.loggedIn? <><div id="noLogin_review_cont">
      <p>Looks like you're not logged in.</p>
      <p>Login here so you can show your spirit: </p><Link id="review_login" to="/login">Login Here</Link>
    </div></> : <>
      <div id="noLogin_review_cont">
        <p>Please add the anime to your list to create a review.</p>
        <button onClick={(e)=>go_to_add(e)} id="review_login">Close</button>
      </div>
    </>}
  </>
    
  )
}

export default ViewerOut;