import React, { useState, useEffect, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import $ from 'jquery';
import axios  from 'axios';
import { first_ten, sort } from '../utilities/util2';
import txt from '../settings/setting.json';
//import {useState} from 'react';

const baseURL = "https://infernovertigo.pythonanywhere.com";

axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.xsrfHeaderName = "X-CSRFToken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL:baseURL
})

const Nav = (props) => {
  const [allowSearchUpdate, setSearchUpdate] = useState(true);
  const limit = 10;
  var timeout = null;
  const delay = 1500;
  const navigate = useNavigate();
  var FocusingOut = false;
  const [data_list, loadDL] = useState([]);
  const [isReady, setReady] = useState(false);
  const controller = new AbortController();
  const signal = controller.signal;
  const changer = txt.changer;

  useEffect(()=>{
    //setReady(true);
    //return;
    document.getElementsByClassName("search_input")[0].setAttribute("placeholder", "Search Off")
    async function load(){
      const res = await fetch(baseURL+"/navLoad", {
        "method":"GET",
        signal:signal
      }).then((data)=>data.json())
      //console.log(res);
      loadDL((obj)=>[...res["results"]]);
      setReady(true);
      document.getElementsByClassName("search_input")[0].setAttribute("placeholder", "Search for anime...")
    }
    load()
  }, []);

  async function get_anime_info(id){
    navigate(`/anime/${id+changer}`);
  }

  function search(e, setEmpty=false){
    if(isReady){
      const result_holder = document.getElementsByClassName("result_list")[0];
      const search_load_string = document.getElementById("searching")
      result_holder.innerHTML = "";
      search_load_string.innerHTML = `Searching for ${e.target.value} ...`;
      search_load_string.style.display = "block";

      if(e.target.value == ""){
        result_holder.innerHTML = "";
        search_load_string.innerHTML = "";
        search_load_string.style.display = "none";
      }

      if(setEmpty){
        result_holder.style.display="none";
        search_load_string.innerHTML = "";
        search_load_string.style.display = "none";
        return;
      }

      clearTimeout(timeout);
      timeout = setTimeout(async ()=>{
        result_holder.innerHTML = "";
        let value = e.target.value.toString().toLowerCase().replace(/[-\:\,\"\[\]\;\'\+\=\!\`\~\(\)\*\&\^\%\$\>\<\?\/\\ ]+/g, "").trim();
        //let value = e.target.value.toString().toLowerCase().trim();
        if(value.length == 0 || value==undefined || value==" "){
          setSearchUpdate(()=>true);
          return;
        }
        function get_size(title1, title2){
          if(title1.length > 0){
            return title1.length;
          }else{
            return title2.length;
          }
        }
        //console.log(e.target.value)
        let count = 0;
        const userInputLength = value.length;
        let showsList = [];
        setSearchUpdate(()=>true);
        
        //const startList = searchList[value[0]].slice(0,100);
        let valueList = [];
        /*const res = await client.post("anime/SearchV2", {val:value}, {"headers":{"Content-Type":"application/json"}})
        .then((data)=>data.data);
        console.log(res);
        //console.log(keys.slice(1000,2000))
        return;*/
        for(let i=0; i< data_list.length; i++){
          const title = data_list[i]["english_name"].replace(/[-\:\,\"\[\]\;\'\+\=\!\`\~\(\)\*\&\^\%\$\>\<\?\/\\ ]+/g, "").toLowerCase().trim();
          const title2 = data_list[i]["japanese_name"].replace(/[-\:\,\"\[\]\;\'\+\=\!\`\~\(\)\*\&\^\%\$\>\<\?\/\\ ]+/g, "").toLowerCase().trim();
          //const title = "ReZEROStartingLifeinAnotherWorld".toLowerCase();
          if(count == 10){
            break;
          }
          let stepThrough = 0;
          let matches = 0;
          let inArow = 0;
          let previousJapName = null;
          let previousEngName = null;
          if(value.substring(0, value.length) == title.substring(0, value.length) || value.substring(0, value.length) == title2.substring(0, value.length)){
            let matches = value.length/title.length;
            let matches2 = value.length/title2.length;
            
            if(title2.length == 0){
              matches2=-1;
            }
            if(title.length == 0){
              matches=-1;
            }
            //console.log(matches)
            valueList.push([1.0+matches, data_list[i]["anime_id"], data_list[i]["title"], data_list[i]["img_url"], data_list[i]["start_date"], data_list[i]["end_date"]])
            valueList.push([1.0+matches2, data_list[i]["anime_id"], data_list[i]["title"], data_list[i]["img_url"], data_list[i]["start_date"], data_list[i]["end_date"]])
            continue;
          }
          let trigger = false;

          outter1:for(let k=0; k < value.length; k++){
            inner1:for(let h=stepThrough; h < get_size(title, title2); h++){
              let breakout = [false, false];
              if(title.length != 0 && stepThrough == title.length-1){
                let matched = matches/title.length;
                //console.log(matched)
                valueList.push([matched,  data_list[i]["anime_id"], data_list[i]["title"], data_list[i]["img_url"], data_list[i]["start_date"], data_list[i]["end_date"]])
                //valueList.push([matched, "re zero stuff"]);
                breakout[0] = true;
                //break outter1;
              }if(title2.length != 0 && stepThrough == title2.length-1){
                let matched = matches/title2.length;
                //console.log(matched)
                valueList.push([matched,  data_list[i]["anime_id"], data_list[i]["title"], data_list[i]["img_url"], data_list[i]["start_date"], data_list[i]["end_date"]])
                //valueList.push([matched, "re zero stuff"]);
                breakout[1] = true;
                //break outter1;
              }
              if(breakout[0] == true || breakout[1] == true){
                break outter1;
              }
              if(inArow>1){
                matches+=1;
                //console.log(title);
              }
              if(value.charAt(k) == title.charAt(stepThrough) || value.charAt(k) == title2.charAt(stepThrough)){
                if(trigger == true){
                  stepThrough+=1
                  continue inner1;
                }

                stepThrough = h;
                inArow+=1;
                stepThrough+=1;
                matches +=1;

                if(k == value.length-1){
                  trigger=true;
                  continue inner1;
                }
                break inner1;
              }
              inArow = 0;
              stepThrough+=1;
            }
          }
        }
        
        const data = first_ten(sort(valueList));

        let img;
        let start;
        let end;

        let begin = data.length-1;
        for(let j=0; j<data.length; j++){
          if(data[j] == undefined){
            continue;
          }
          try{
            start = data[j][4]
          }catch{
            start = ""
          }
          try{
            end = data[j][5]
          }catch{
            end = ""
          }
          search_load_string.innerHTML = "";
          result_holder.innerHTML = result_holder.innerHTML + `<div class="result">`+
          `<img src=${data[j][3]} height='100px' width='70px'/>` +
          `<div class='search_info'>`+
          `<h1>${data[j][2]}</h1>`+
          `</div>`
          search_load_string.style.display="none";
        }

        //last for loop that adds a function to each result. the function sends to linked anime details page.
        for(let k=0; k<result_holder.children.length; k++){
          result_holder.children[k].addEventListener("click", ()=>{
            //console.log("Placebo of doom");
            get_anime_info(data[k][1])});
        }

        //console.log(valueList);
      }, delay)
      return;
    }
    
  }
  var timeout2 = null;

  useEffect(()=>{
    $(".search_input").focusin(function(e){
      const result_holder = document.getElementsByClassName("result_list")[0];
      result_holder.style.display="block";
    })

    $(".search_input").focusout(function(e){
      if(!FocusingOut){
        setTimeout(()=>{
          const search_load_string = document.getElementById("searching")
          FocusingOut = true;
          const result_holder = document.getElementsByClassName("result_list")[0];
          result_holder.style.display="none";
          FocusingOut = false;
          search_load_string.style.display="none";
          //console.log("clear everything");
        }, 200)
      }
      
      //search(e, true);
    })

    $("form").submit(function(e){
      e.preventDefault();
      console.log("don't reload")
    })
  },[])

  /*$(window).resize(function(){
    const result_holder = document.getElementsByClassName("result_list")[0];
    clearTimeout(timeout2);
    timeout2 = setTimeout(()=>{
      for(let k = 0; k<result_holder.children.length; k++){
        if(result_holder.children[k].scrollHeight > 100){
          result_holder.children[k].style.overflowY="scroll";
          result_holder.children[k].style.overflowX="hidden";
        }
      }
    }, delay-1000)
  })*/

  function redirectLeaderboard(e){
    props.setRedirect("leaderboard");
    //console.log(props);
    //navigate("/redirect", {state:"leaderboard"});
    navigate("/leaderboard/1");
  }

  function redirect(page){
    if(page == "home"){
      //navigate("/redirect", {state:"home"});
      navigate("/");
    }
    if(page == "about"){
      //navigate("/redirect", {state:"about"});
      navigate("/about");
    }
    if(page == "users"){
      navigate("/users");
    }
  }

  return (
    <div className='nav-container'>
    <nav className='ViewQueue'>
        <div className='left'>
          <Link to="/" className="Link"><button>Home</button></Link>
          {/*JSON.parse(localStorage.getItem("hidden"))  || JSON.parse(localStorage.getItem("logged_in"))? 
          <Link className="Link" to="/queue"><button>The Queue</button></Link> 
          : <></>*/}
          {<Link className="Link" to="/users"><button>Users</button></Link>}
          {/*<Link className="Link" to="/"><button>Maintanence</button></Link>*/}
          {/*JSON.parse(localStorage.getItem("hidden")) || JSON.parse(localStorage.getItem("logged_in"))?
          <Link className="Link" to="/stats"><button>Stats</button></Link>
          : <></>*/}
          <Link to="/about" className="Link"><button>About</button></Link>
          
          <div className='search-box'>
            {(props.showSearch === true) && (
              <form>
                <input
                onKeyUp={e=>search(e)}
                className='search_input'
                value={props.search} 
                //onChange={e=>search_results(e)}
                type="search" 
                placeholder='Search for anime...'/>  
                <p id="searching">Searching For (show name) ...</p>
                <div className="search_results">
                  <div className="result_list">

                  </div>
                </div> 
              </form>
              )}
          </div>
        </div>
      </nav>
      </div>
  )
}

export default Nav