function month_to_str(month_num){
  const months={1:"Jan", 2:"Feb", 3:"Mar", 4:"Apr", 5:"May", 6:"Jun", 
  7:"Jul", 8:"Aug", 9:"Sep", 10:"Oct", 11:"Nov", 12:"Dec"}

  return months[month_num+1];
}
function date_to_review(format){
  let date = new Date(format.replace(" ", "T"));

  const offset = date.getTimezoneOffset() * (60 * 1000);
  if(offset>0){
    date.setTime(date.getTime()-offset);
  }else{
    date.setTime(date.getTime()+offset);
  }
  
  return `${month_to_str(date.getMonth())} ${date.getDate()}, ${date.getFullYear()}`
}
