async function bannable(value){
  //console.log(value);
  const banned_words = await fetch(raw).then((data)=>data.text());
  const words = banned_words.split(",");
  for(let i=0; i<words.length; i++){
    for(let k=0; k<value.length; k++){
      let formed_word = "";
      for(let j=k; j<value.toLowerCase().length; j++){
        formed_word += value.toLowerCase().charAt(j);
        if(formed_word == words[i]){
          //console.log(words[i])
          //console.log(words[i], formed_word)
          /*errorLabel.innerHTML="Banned Word";
          errorLabel.style.visibility="visible";
          setErrorUser((obj)=>{return true;});*/
          //return true;
          return formed_word;
        }
      }
    }
  }
  //return false;
  return "";
}

function capitalize_first_letter(str){
  try{
    let temp = "";
    let count = 0;
    for(let i = 0; i < str.length; i++){
      if(count == 0){
        temp += str[i].toUpperCase();
        count+=1;
        continue;
      }
      if(str[i] == ' '){
        count=0
      }
      temp+=str[i]
    }
    return temp;
  }catch{
    return;
  }
}

