import React, { useEffect, useState } from 'react'
import $ from 'jquery';

export default function Settings() {
  const [useEnglish, setUseEnglish] = useState(false);
  var previous = null;

  useEffect(()=>{
    const language_choice = localStorage.getItem("title_lang");
    $("document").ready(function(){
        $("#lang_ins1, #lang_ins2").ready(function(){
          if(language_choice != null){
            setUseEnglish(JSON.parse(language_choice));
            if(JSON.parse(language_choice) == false){
              $("#lang_ins1").attr("checked", true);
              $("#lang_ins1").attr("disabled", true);

              $("#lang_ins2").attr("checked", false);
            }else{
              $("#lang_ins1").attr("checked", false);

              $("#lang_ins2").attr("checked", true);
              $("#lang_ins2").attr("disabled", true);
            }
          }else{
            localStorage.setItem("title_lang", false);
            $("#lang_ins1").attr("checked", true);
            $("#lang_ins1").attr("disabled", true);

            $("#lang_ins2").attr("checked", false);
          }
        })
      }
    );
  }, []);

  function change_title_language(e){
    let language_choice = JSON.parse(localStorage.getItem("title_lang"));
    if(language_choice){
      $("#lang_ins1").attr("checked", true);
      $("#lang_ins1").attr("disabled", true);

      $("#lang_ins2").attr("checked", false);
      $("#lang_ins2").attr("disabled", false);
      localStorage.setItem("title_lang", false);
    }else{
      $("#lang_ins1").attr("checked", false);
      $("#lang_ins1").attr("disabled", false);

      $("#lang_ins2").attr("checked", true);
      $("#lang_ins2").attr("disabled", true);
      localStorage.setItem("title_lang", true);
    }
  }

  return (
    <div>
      <form class="settings_cont">
        <label>Display title by the English title or Japanese title:</label>
        <br></br>
        <input id="lang_ins1" type="radio" onClick={(e)=>change_title_language(e)} name="lang" value="en"></input><label for="lang_ins1">English When Available</label>
        <br></br>
        <input id="lang_ins2" type="radio" onClick={(e)=>change_title_language(e)} name="lang" value="jp"></input><label for="lang_ins2">Japanese When Available</label>
      </form>
    </div>
  )
}
