function get_ten(arr, limit=10){
  let count = 0;
  let temp = [];
  let prev = [];

  outter:for(let k = 0; k < arr.length; k++){
    if(count == limit){
      break;
    }

    for(let i = 0; i < prev.length;i++){
      if(prev[i] == arr[k][1]){
        continue outter;
      }
    }
    temp.push((arr[k]));
    prev.push(arr[k][1]);
    count+=1;
  }

  return temp;
}
function merge(left, right) {
  let sortedArr = [] // the sorted items will go here
  while (left.length && right.length) {
    // Insert the smallest item into sortedArr
    if (left[0] > right[0]) {
      sortedArr.push(left.shift())
    } else {
      sortedArr.push(right.shift())
    }
  }
  // Use spread operators to create a new array, combining the three arrays
  return [...sortedArr, ...left, ...right]
}

function merge_sort(arr){
  if (arr.length <= 1) return arr

  const halfMax = Math.floor(arr.length/2)

  let left = merge_sort(arr.slice(0, halfMax));
  let right = merge_sort(arr.slice(halfMax, arr.length));

  return merge(left, right);

    let l, k, r = 0;

    while(l < left.length & r < right.length){
      if(left[l][0] < right[r][0]){
        left[l] = arr[k];
        l++;

      }else{
        right[r] = arr[k];
        r++;
      }
      k++;
    }

    while(l < left.length){
      left[l] = arr[k];
      k++;
      l++;
    }

    while(r < right.length){
      right[l] = arr[k];
      k++;
      r++;
    }
}

function linearSearch(list, val){
  let front = 0;
  let back = list.length -1

  while (front <= back){
    if(list[front]["user_id_id"] == val){
      return front;
    }
    if(list[back]["user_id_id"] == val){
      return back;
    }
    front += 1;
    back -= 1;
  }
}

function rerank(User_rank, stuff){
  if(User_rank == 0){
    stuff.innerText = " THE KING " + String.fromCharCode(0xD83D, 0xDC51);
    stuff.style.color="gold";
  }else if(User_rank == 1){
    stuff.innerText = (User_rank + 1).toString() + " Nothing But Respect";
    stuff.style.color="silver";
  }else if(User_rank == 2){
    stuff.innerText = (User_rank + 1).toString() + " Well Earned ";
    stuff.style.color="bronze";
  }else{
    stuff.innerText = User_rank + 1;
  }
}

async function runBoard(users, user_id=0, mode=0){
  const banned_from_list = ["AnimePu55y", "NierBeloved", "Zupay"];
  const table = document.getElementById("leaderboard_table");
  const rows = document.getElementsByClassName("removable");

  let idx = 0;
  let key = "";

  if(mode <= 0){
    idx = 0;
  }else{
    idx = 1;
  }

  for(let i = rows.length-1; i>-1; i--){
    rows[i].remove();
  }

  document.getElementById("redirect_cont").style.display="table-cell";
  
  const User_rank = linearSearch(users[idx], user_id);

  const stuff = document.getElementById("usr_rank");
  rerank(User_rank, stuff);

  const online_status = document.createElement("span");
  online_status.appendChild(document.createTextNode("."));
  online_status.setAttribute("class", "online");

  users[idx].map((obj, indx)=>{ 
    const tr = document.createElement("tr");
    const td0 = document.createElement("td"); //rank
    const td1 = document.createElement("td"); //username
    const td2 = document.createElement("td"); //episodes
    const td3 = document.createElement("td"); //completed
    
    tr.setAttribute("class", "subRows removable");

    let rank = document.createTextNode((indx + 1).toString())
    
    if(indx == 0){tr.setAttribute("id", "firstPlace")}
    if(indx == 1){tr.setAttribute("id", "secondPlace")}
    if(indx == 2){tr.setAttribute("id", "thirdPlace")}

    let user_link = document.createElement("a");
    user_link.setAttribute("href", `#/user/${obj["username"]}`);
    let textUser = document.createTextNode(obj["username"]);
    
    user_link.appendChild(textUser);
  
    let watched = null;
    let finished = null;
    watched = document.createTextNode(users[idx][indx]["episodes_watched"]);
    finished = document.createTextNode(obj["completed_shows"]);
  

    //let tournieUser = document.createTextNode(obj[1]);

    //sets numbering system and highlights logged in user
    
    if(User_rank != -1){
      if(User_rank == indx){
        td0.setAttribute("id", "your_person")
        td0.appendChild(document.createTextNode("You"))
      }else{
        td0.appendChild(rank);
      }
    }else{
      td0.appendChild(rank);
    }

    td1.setAttribute("class", "username_links");
    td1.appendChild(user_link);
    td2.appendChild(watched);
    td3.appendChild(finished);

    tr.appendChild(td0);
    tr.appendChild(td1);
    tr.appendChild(td2);
    tr.appendChild(td3);

    table.appendChild(tr);
    
  });

  document.getElementById("redirect_cont").style.display="none";
}

function reverse(object){
  if(typeof(object) == "string"){
    let build = "";
    for(let i = object.length-1; i >= 0; i--){
      build += object.charAt(i);
    }
    return build;
  }

  if(typeof(object) == "object"){
    const size = object.length;
    let count = 0;
    if(size % 2 == 0){
      for(let i = 0; i < size; i++){
        if(i == size/2){
          break;
        }
        let temp = object[i];
        object[i] = object[size-1-count];
        object[size-1-count] = temp;
        count+=1;
      }
    }else{
      for(let i = 0; i < size; i++){
        if(i > size/2){
          break;
        }
        let temp = object[i];
        object[i] = object[size-1-count];
        object[size-1-count] = temp;
        count+=1;
      }
    }
    return object;
  }
}

