function calculate_genres(genre_cats, queues_genres){
  let object = {};
  let splitter = [];
  //console.log(queues_genres);
  for(let i = 0; i < queues_genres.length; i++){
    const val = queues_genres[i][0];
    if(val != null){
      splitter = val.split(",");
    }else{
      continue;
    }

    if(splitter[0] == ""){
      continue;
    }

    for(let k = 0; k < splitter.length; k++){
      const key = splitter[k].trim();
      if(object[key] == null){
        object[key] = 1;
      }else{
        object[key] = object[key]+1;
      }
    }
  }

  return object;
}

function calculate_scores(scores){
  let object = {};
  let avg = 0;

  for(let i = 0; i < scores.length; i++){
    const key = scores[i];
    if(object[key] == null){
      object[key] = 1;
      avg = avg + Number(key);
    }else{
      object[key] = object[key]+1;
      avg = avg + Number(key);
    }
  }

  //console.log(avg/scores.length, "avg");
  //console.log(object, "objects");

  return [avg/scores.length, object];
}

function notify(e, notification, color, milli=5000){
  const noti = document.getElementById("notifications");
    noti.style.display = "block";
    //noti.style.backgroundColor = "red";
    noti.style.backgroundColor = color;
    //noti.innerText = "Problem updating your list. Please try again later.";
    noti.innerText = notification;
    setTimeout(()=>{
      noti.style.display = "none";
      e.target.disabled = false;
    }, milli)
}

